SELECT * 
FROM customers 
WHERE points > 3000;

SELECT * 
FROM customers 
WHERE state = 'VA';

SELECT * 
FROM customers 
WHERE birth_date > '1990-01-01' AND points > 1000;

SELECT * 
FROM customers 
WHERE birth_date > '1990-01-01' OR points > 1000;

SELECT * 
FROM customers 
WHERE NOT (birth_date > '1990-01-01' OR points > 1000);

SELECT * 
FROM customers 
ORDER BY first_name;

SELECT * 
FROM customers 
ORDER BY points DESC;

SELECT * 
FROM customers 
ORDER BY state, first_name;

SELECT * 
FROM order_items 
WHERE order_id = 6 AND (quantity * unit_price) > 30;

USE sql_store;

SELECT * 
FROM order_items oi 
JOIN sql_inventory.products p 
  ON oi.product_id = p.product_id;

SELECT c.color_name, s.size_name 
FROM colors c 
CROSS JOIN sizes s;

UPDATE customers 
SET points = points * 1.5 
WHERE points > 0;
